<?php
declare(strict_types=1);
require __DIR__.'/../bootstrap.php';
use Ismile\App;use Ismile\Auth;use Ismile\Db;use Ismile\WorkshopCashSale;use Ismile\WorkshopCheckout;use Ismile\UserError;
if(App::isLive()||!str_starts_with((string)App::config('db.name'),'ismile_workshop_test_online_')||App::config('payments.psoola.api_base')!=='http://127.0.0.1:8832')throw new RuntimeException('Isolated free workshop fixture required.');
$passed=0;$check=static function(string $name,bool $ok)use(&$passed):void{if(!$ok)throw new RuntimeException('FAILED: '.$name);$passed++;echo 'PASS: '.$name.PHP_EOL;};
$reject=static function(callable $fn):bool{try{$fn();return false;}catch(UserError){return true;}};
$fixture=static fn(string $query=''):array=>json_decode((string)file_get_contents('http://127.0.0.1:8832/fixture'.$query),true);
$row=json_decode(file_get_contents(__DIR__.'/../assets/subperiosteal-workshop-2026.json'),true);$row['id']='staff-free-workshop';$row['provider_event_id']='fixture-free-event';$row['provider_show_id']='fixture-free-show';$row['provider_ticket_type_id']='fixture-free-ticket';$row['status']='active';
Db::insert('workshops',$row+['sort_order'=>10,'created_at'=>App::now(),'updated_at'=>App::now()]);
$fixture('/stock?workshop=subperiosteal-implant-protocol&available=30');
$staffId=Auth::createUser('zero-workshop-staff@example.invalid','Workshop Staff','registration',bin2hex(random_bytes(16)));$staff=Db::one('SELECT * FROM admin_users WHERE id=?',[$staffId]);
$seed=static function(string $suffix,string $status='paid',?string $email=null):array{$id=Db::insert('registrations',['ref'=>'ZF'.strtoupper(bin2hex(random_bytes(5))),'first_name'=>'Free','father_name'=>'Workshop','grandfather_name'=>$suffix,'email'=>$email??'staff-free-'.$suffix.'@example.invalid','phone'=>'+9647501234567','city'=>'Sulaimani','specialty'=>'gp','ticket_type'=>'professional','status'=>$status,'comp_reason'=>$status==='complimentary'?'Fixture':null,'view_nonce'=>bin2hex(random_bytes(16)),'created_at'=>App::now(),'updated_at'=>App::now(),'paid_at'=>App::now()]);return Db::one('SELECT * FROM registrations WHERE id=?',[$id]);};
$person=$seed('attendee');$input=['workshop'=>$row['id'],'free_registration'=>'1'];$before=$fixture();$receipts=(int)Db::value('SELECT COUNT(*) FROM workshop_cash_receipts');$payments=(int)Db::value('SELECT COUNT(*) FROM payments');$guests=(int)Db::value('SELECT COUNT(*) FROM guest_workshop_orders');
$check('Ordinary registration staff can assist without guest issuance access',Auth::canBookWorkshops($staff)&&!Auth::canIssueComplimentary($staff));
$check('Viewer cannot issue an assisted free ticket',$reject(fn()=>WorkshopCashSale::register($person,['id'=>$staffId,'role'=>'viewer'],$input)));
$check('Free registration cannot record cash',$reject(fn()=>WorkshopCashSale::register($person,$staff,$input+['cash_amount'=>'1'])));
$check('Guest and cancelled summit registrations stay ineligible',$reject(fn()=>WorkshopCashSale::register($seed('guest','complimentary'),$staff,$input))&&$reject(fn()=>WorkshopCashSale::register($seed('cancelled','cancelled'),$staff,$input)));
$check('Paid workshop cannot be submitted as a free staff registration',$reject(fn()=>WorkshopCashSale::register($person,$staff,array_replace($input,['workshop'=>'simplified-direct-veneers']))));
$check('Rejected requests create no provider session',$fixture()['creations']===$before['creations']);
$old=$seed('old-paid-attempt');Db::insert('workshop_checkouts',['registration_id'=>$old['id'],'workshop_id'=>$row['id'],'public_token'=>bin2hex(random_bytes(32)),'idempotency_key'=>'staff-old-'.bin2hex(random_bytes(8)),'partner_reference'=>'staff-old-'.bin2hex(random_bytes(8)),'request_json'=>'{}','amount'=>100,'currency'=>'IQD','created_at'=>App::now(),'updated_at'=>App::now()]);$check('An older chargeable request cannot be reused as a free ticket',$reject(fn()=>WorkshopCashSale::register($old,$staff,$input))&&$fixture()['creations']===$before['creations']);
$message=WorkshopCashSale::register($person,$staff,$input);$attempt=Db::one('SELECT * FROM workshop_checkouts WHERE registration_id=? AND workshop_id=?',[$person['id'],$row['id']]);$booking=Db::one('SELECT * FROM workshop_bookings WHERE id=?',[$attempt['booking_id']]);$body=json_decode($attempt['request_json'],true);
$check('Staff request confirms a verified normal zero-IQD provider ticket',$attempt['provider_status']==='paid'&&(int)$attempt['amount']===0&&$booking['payment_status']==='paid'&&(int)$booking['price_agreed']===0&&(int)$booking['amount_paid']===0&&str_contains($message,'0 IQD'));
$check('Provider receives the configured ticket, one attendee and no complimentary override',$body['items']===[['ticketTypeId'=>'fixture-free-ticket','quantity'=>1]]&&$body['buyer']['email']===$person['email']&&!isset($body['isComplimentary']));
$check('Registration identifies the assisting staff member',(int)$booking['booked_by']===$staffId&&str_contains($booking['notes'],'No cash collected'));
$check('No cash receipt, summit payment or guest order is created',(int)Db::value('SELECT COUNT(*) FROM workshop_cash_receipts')===$receipts&&(int)Db::value('SELECT COUNT(*) FROM payments')===$payments&&(int)Db::value('SELECT COUNT(*) FROM guest_workshop_orders')===$guests&&$fixture()['direct']===$before['direct']);
$count=count($fixture()['sessions']);$check('Double submission cannot issue a second ticket',$reject(fn()=>WorkshopCashSale::register($person,$staff,$input))&&count($fixture()['sessions'])===$count);
$lost=$seed('lost-response');$check('A lost response is kept for retry',$reject(fn()=>WorkshopCashSale::register($lost,$staff,$input)));
$count=count($fixture()['sessions']);WorkshopCashSale::register($lost,$staff,$input);$check('Retry after lost response confirms the same provider session',count($fixture()['sessions'])===$count&&Db::value('SELECT provider_status FROM workshop_checkouts WHERE registration_id=? AND workshop_id=?',[$lost['id'],$row['id']])==='paid');
$shared=$seed('selected','paid','staff-shared@example.invalid');$newer=$seed('newer','paid',$shared['email']);WorkshopCashSale::register($shared,$staff,$input);$check('Selected registration is preserved when attendees share an email',(int)Db::value('SELECT COUNT(*) FROM workshop_checkouts WHERE registration_id=? AND workshop_id=?',[$shared['id'],$row['id']])===1&&(int)Db::value('SELECT COUNT(*) FROM workshop_checkouts WHERE registration_id=? AND workshop_id=?',[$newer['id'],$row['id']])===0);
$session=['id'=>$attempt['provider_session_id'],'partnerReference'=>$attempt['partner_reference'],'order'=>['items'=>$body['items'],'totalAmount'=>1,'currency'=>'IQD']];try{WorkshopCheckout::validate($attempt,$session);$mismatch=false;}catch(RuntimeException){$mismatch=true;}$check('A nonzero provider total cannot confirm a free ticket',$mismatch);
$fixture('/stock?workshop=subperiosteal-implant-protocol&available=0');$check('Sold out provider inventory blocks staff registration',$reject(fn()=>WorkshopCashSale::register($seed('soldout'),$staff,$input)));
echo $passed.' free staff workshop checks passed.'.PHP_EOL;
